#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node* next;
} Node;

void append(Node** head, int value) {
    Node* node = malloc(sizeof(Node));
    node->value = value;
    node->next = NULL;
    if (*head == NULL) {
        *head = node;
        return;
    }
    Node* last = *head;
    while (last->next != NULL) {
        last = last->next;
    }
    last->next = node;
}

int main(void) {
    Node* head = NULL;
    append(&head, 10);
    append(&head, 20);
    append(&head, 30);
    for (Node* n = head; n != NULL; n = n->next) {
        printf("%d -> ", n->value);
    }
    printf("NULL\n");
    while (head != NULL) {
        Node* tmp = head;
        head = head->next;
        free(tmp);
    }
    return 0;
}

